using System;
using System.Runtime.CompilerServices;

namespace PdfToSvg.Collections
{
    // Shared class for statically compiled hash tables with string keys.
    //
    // The idea is to move the hash table construction time from runtime to compile time.
    //
    // In the first attempt, static methods with decision trees were generated by he source generator, but it turned out
    // to perform better by constructing a regular hash table and only have general lookup logics in production code.
    //
    // The class is only intended for short string keys.
    //
    // The lookup method expects an index array with interleaved start and end indexes of the entry array.
    internal static class StringHashTable
    {
        private const int CharsInHashCode = 3;

        public readonly struct Entry<T>(string key, int hashCode, T value)
        {
            public readonly string Key = key;
            public readonly int HashCode = hashCode;
            public readonly T Value = value;
        }

        public static Entry<T> CreateEntry<T>(string key, int hashCode, T value) => new Entry<T>(key, hashCode, value);

        // Implementation must match source generators!
        [MethodImpl(MethodInliningOptions.AggressiveInlining)]
        private static int GetHashCode(byte[] buffer, int length)
        {
            var hashCode = length;

            for (var i = 0; i < buffer.Length && i < length && i < CharsInHashCode; i++)
            {
                hashCode = unchecked((hashCode << 8) | buffer[i]);
            }

            return hashCode;
        }

        // Implementation must match source generators!
        [MethodImpl(MethodInliningOptions.AggressiveInlining)]
        private static int GetHashCode(string value)
        {
            var hashCode = value.Length;

            for (var i = 0; i < value.Length && i < CharsInHashCode; i++)
            {
                hashCode = unchecked((hashCode << 8) | (byte)value[i]);
            }

            return hashCode;
        }

        [MethodImpl(MethodInliningOptions.AggressiveInlining)]
        public static bool TryLookup<T>(
            byte[] buffer, int length,
            uint[] indexes, Entry<T>[] entries,
            uint multiplier, int shiftCount,
            out T result)
        {
            var hashCode = GetHashCode(buffer, length);
            var bucket = unchecked((uint)hashCode * multiplier) >> shiftCount;

            var endIndex = indexes[bucket + 1];
            var startIndex = indexes[bucket];

            for (var entryIndex = startIndex; entryIndex < (uint)entries.Length && entryIndex < endIndex; entryIndex++)
            {
                ref var entry = ref entries[entryIndex];

                if (entry.HashCode == hashCode)
                {
                    if (length <= CharsInHashCode)
                    {
                        result = entry.Value;
                        return true;
                    }

                    var entryKey = entry.Key;

                    if (entryKey.Length == length)
                    {
                        var match = true;

                        for (var i = CharsInHashCode; i < buffer.Length && i < entryKey.Length; i++)
                        {
                            if ((byte)entryKey[i] != buffer[i])
                            {
                                match = false;
                                break;
                            }
                        }

                        if (match)
                        {
                            result = entry.Value;
                            return true;
                        }
                    }
                }
            }

            result = default!;
            return false;
        }

        [MethodImpl(MethodInliningOptions.AggressiveInlining)]
        public static bool TryLookup<T>(
            string value,
            uint[] indexes, Entry<T>[] entries,
            uint multiplier, int shiftCount,
            out T result)
        {
            var hashCode = GetHashCode(value);
            var bucket = unchecked((uint)hashCode * multiplier) >> shiftCount;

            var endIndex = indexes[bucket + 1];
            var startIndex = indexes[bucket];

            for (var entryIndex = startIndex; entryIndex < (uint)entries.Length && entryIndex < endIndex; entryIndex++)
            {
                ref var entry = ref entries[entryIndex];

                if (entry.HashCode == hashCode)
                {
                    // In the byte buffer overload we can skip checking the leading characters included in the hash code
                    // but we can't do so in the string overload since the chars can be > 255
                    //
                    // if (value.Length <= CharsInHashCode)
                    // {
                    //     result = entry.Value;
                    //     return true;
                    // }

                    var entryKey = entry.Key;

                    if (entryKey.Length == value.Length)
                    {
                        var match = true;

                        // Byte buffer overload starts at `i = CharsInHashCode`. We can't do it here, see comment above
                        for (var i = 0; i < value.Length && i < entryKey.Length; i++)
                        {
                            if (entryKey[i] != value[i])
                            {
                                match = false;
                                break;
                            }
                        }

                        if (match)
                        {
                            result = entry.Value;
                            return true;
                        }
                    }
                }
            }

            result = default!;
            return false;
        }
    }
}
